import React, { useState, useEffect } from 'react';
import { Briefcase, GraduationCap, Stethoscope, Search, Menu, X, Sun, Moon, Mic, Loader2, Mail, Star, Lightbulb, Network, UserCheck, Compass, Zap, ChevronRight } from 'lucide-react';
import { JOB_SITES, LEARNING_SITES, INTERVIEW_SITES, PROFESSIONAL_ADVICE } from './constants';
import { ResourceCard } from './components/ResourceCard';
import { ChatConsultant } from './components/ChatConsultant';

const Tab = {
  JOBS: 'JOBS',
  LEARNING: 'LEARNING',
  INTERVIEW: 'INTERVIEW',
  ADVICE: 'ADVICE',
  CONSULTANT: 'CONSULTANT'
} as const;

type TabType = typeof Tab[keyof typeof Tab];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>(Tab.JOBS);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(true);
  const [jobSearch, setJobSearch] = useState('');
  const [showOnlyRecommendedJobs, setShowOnlyRecommendedJobs] = useState(false);
  const [isContentVisible, setIsContentVisible] = useState(true);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const toggleMobileMenu = () => setIsMobileMenuOpen(!isMobileMenuOpen);
  const toggleTheme = () => setDarkMode(!darkMode);

  const handleTabChange = (tab: TabType) => {
    if (tab === activeTab) {
      if (isMobileMenuOpen) setIsMobileMenuOpen(false);
      return;
    }

    setIsContentVisible(false);
    if (isMobileMenuOpen) setIsMobileMenuOpen(false);

    setTimeout(() => {
      setActiveTab(tab);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setIsLoading(true);

      setTimeout(() => {
        setIsLoading(false);
        setTimeout(() => setIsContentVisible(true), 50);
      }, 400);
    }, 300);
  };

  const renderContent = () => {
    switch (activeTab) {
      case Tab.JOBS:
        let filteredJobs = JOB_SITES.filter(site => 
          site.name.toLowerCase().includes(jobSearch.toLowerCase()) ||
          site.description.toLowerCase().includes(jobSearch.toLowerCase())
        );

        if (showOnlyRecommendedJobs) {
          filteredJobs = filteredJobs.filter(site => site.recommended);
        }

        return (
          <div className="space-y-8 animate-fadeIn">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-4">לוחות דרושים מומלצים</h2>
              <p className="text-slate-600 dark:text-slate-300 max-w-2xl mx-auto mb-8">
                ריכזנו עבורך את האתרים הטובים ביותר למציאת העבודה הבאה שלך. 
                ממשרות הייטק ועד משרות ממשלתיות.
              </p>

              <div className="flex flex-col md:flex-row gap-4 max-w-2xl mx-auto">
                <div className="flex-1 relative">
                  <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                    <Search className="h-5 w-5 text-slate-400" />
                  </div>
                  <input
                    type="text"
                    className="block w-full pr-10 p-3 border border-slate-300 dark:border-slate-600 rounded-full leading-5 bg-white dark:bg-slate-800 text-slate-900 dark:text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-medical-500 focus:border-medical-500 sm:text-sm shadow-sm transition-colors"
                    placeholder="חיפוש אתר דרושים..."
                    value={jobSearch}
                    onChange={(e) => setJobSearch(e.target.value)}
                  />
                </div>

                <button
                  onClick={() => setShowOnlyRecommendedJobs(!showOnlyRecommendedJobs)}
                  className={`flex items-center justify-center gap-2 px-6 py-3 rounded-full font-medium transition-all shadow-sm border ${
                    showOnlyRecommendedJobs 
                      ? 'bg-yellow-400 border-yellow-500 text-yellow-900 shadow-yellow-400/20' 
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-yellow-400'
                  }`}
                >
                  <Star className={`w-4 h-4 ${showOnlyRecommendedJobs ? 'fill-current' : ''}`} />
                  מומלצים בלבד
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredJobs.length > 0 ? (
                filteredJobs.map((site) => (
                  <ResourceCard key={site.url} resource={site} type="job" />
