                        </li>
                      ))}
                    </ul>
                  </div>
                ))}
             </div>
          </div>
        );
      case Tab.CONSULTANT:
        return (
          <div className="max-w-4xl mx-auto h-[calc(100vh-140px)] animate-fadeIn">
             <ChatConsultant />
          </div>
        );
      default:
        return null;
    }
  };

  const NavButton = ({ tab, icon: Icon, label, colorClass = "" }: { tab: TabType, icon: any, label: string, colorClass?: string }) => {
    const isActive = activeTab === tab;
