import { Briefcase, GraduationCap, Stethoscope, Search, Menu, X, Sun, Moon, Mic, Loader2, Mail, Star, Lightbulb, Network, UserCheck, Compass, Zap, ChevronRight, Bot, HelpCircle } from 'lucide-react';
import { JOB_SITES, LEARNING_SITES, INTERVIEW_SITES, PROFESSIONAL_ADVICE, INTERVIEW_QUESTIONS } from './constants';
import { ResourceCard } from './components/ResourceCard';
import { ChatConsultant } from './components/ChatConsultant';

const Tab = {
  JOBS: 'JOBS',
  LEARNING: 'LEARNING',
  INTERVIEW: 'INTERVIEW',
  ADVICE: 'ADVICE',
  CONSULTANT: 'CONSULTANT'
} as const;

type TabType = typeof Tab[keyof typeof Tab];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>(Tab.JOBS);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(true);
  const [jobSearch, setJobSearch] = useState('');
  const [showOnlyRecommendedJobs, setShowOnlyRecommendedJobs] = useState(false);
  const [isContentVisible, setIsContentVisible] = useState(true);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const toggleMobileMenu = () => setIsMobileMenuOpen(!isMobileMenuOpen);
  const toggleTheme = () => setDarkMode(!darkMode);

  const handleTabChange = (tab: TabType) => {
    if (tab === activeTab) {
      if (isMobileMenuOpen) setIsMobileMenuOpen(false);
      return;
    }

    setIsContentVisible(false);
    if (isMobileMenuOpen) setIsMobileMenuOpen(false);

    setTimeout(() => {
      setActiveTab(tab);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setIsLoading(true);

      setTimeout(() => {
        setIsLoading(false);
        setTimeout(() => setIsContentVisible(true), 50);
      }, 400);
    }, 300);
  };

  const renderContent = () => {
    switch (activeTab) {
      case Tab.JOBS:
        let filteredJobs = JOB_SITES.filter(site => 
          site.name.toLowerCase().includes(jobSearch.toLowerCase()) ||
          site.description.toLowerCase().includes(jobSearch.toLowerCase())
