                    <Search className="h-5 w-5 text-slate-400" />
                  </div>
                  <input
                    type="text"
                    className="block w-full pr-10 p-3 border border-slate-300 dark:border-slate-600 rounded-full leading-5 bg-white dark:bg-slate-800 text-slate-900 dark:text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-medical-500 focus:border-medical-500 sm:text-sm shadow-sm transition-colors"
                    placeholder="חיפוש אתר דרושים..."
                    value={jobSearch}
                    onChange={(e) => setJobSearch(e.target.value)}
                  />
                </div>

                <button
                  onClick={() => setShowOnlyRecommendedJobs(!showOnlyRecommendedJobs)}
                  className={`flex items-center justify-center gap-2 px-6 py-3 rounded-full font-medium transition-all shadow-sm border ${
                    showOnlyRecommendedJobs 
                      ? 'bg-yellow-400 border-yellow-500 text-yellow-900 shadow-yellow-400/20' 
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-yellow-400'
                  }`}
                >
                  <Star className={`w-4 h-4 ${showOnlyRecommendedJobs ? 'fill-current' : ''}`} />
                  מומלצים בלבד
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredJobs.length > 0 ? (
                filteredJobs.map((site) => (
                  <ResourceCard key={site.url} resource={site} type="job" />
                ))
              ) : (
                <div className="col-span-full text-center text-slate-500 dark:text-slate-400 py-20 bg-white dark:bg-slate-800/50 rounded-3xl border border-dashed border-slate-200 dark:border-slate-700">
                  <p className="text-lg">לא נמצאו תוצאות עבור החיפוש שלך</p>
                  <button onClick={() => {setJobSearch(''); setShowOnlyRecommendedJobs(false)}} className="mt-4 text-medical-500 font-bold hover:underline">נקה הכל</button>
