export default App;

import React, { useState, useEffect } from 'react';
import { Briefcase, GraduationCap, Stethoscope, Search, Menu, X, Sun, Moon, Mic, Loader2, Mail, Star, Lightbulb, Network, UserCheck, Compass, Zap, ChevronRight, Bot, HelpCircle } from 'lucide-react';
