          </div>
        );
      case Tab.ADVICE:
        return (
          <div className="space-y-10 animate-fadeIn">
             <div className="text-center mb-12">
                <div className="inline-flex p-3 bg-yellow-100 dark:bg-yellow-900/30 rounded-full text-yellow-600 dark:text-yellow-400 mb-4">
